/* --------------------------------------------------------------
 *  Correção de erros de sintaxe, lógica e leitura de arquivos.
 *  Compile com: gcc -Wall -Wextra -o programa programa.c
 * -------------------------------------------------------------- */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 1024          /* tamanho máximo de uma linha */

/* Estruturas definidas conforme o enunciado */
struct Produtos {
    int codigo_produto;
    int qtd_estoque;
    int qtd_minima;
    int qtd_vendida;
    int necessidade_transferencia;
    int qtd_transferencia;
};

struct Vendas {
    int situacao_venda;       /* 0 ou 1 */
    int codigo_produto;
    int quantidade_vendida;
    int canal_venda;
};

int main(void)
{
    FILE *fpProd = fopen("produtos.txt", "r");
    if (!fpProd) {
        perror("Falha ao abrir 'produtos.txt'");
        return 1;
    }

    FILE *fpVendas = fopen("vendas.txt", "r");
    if (!fpVendas) {
        perror("Falha ao abrir 'vendas.txt'");
        fclose(fpProd);
        return 1;
    }

    /* Vetores para armazenar os registros lidos */
    struct Produtos prods[1000];   /* suficiente para os exemplos dados */
    struct Vendas   vends[1000];

    int prodCnt = 0, vendCnt = 0;

    /* ---------- Leitura de produtos (linha: codigo;estoque;min) ---------- */
    while (fscanf(fpProd, "%d;%d;%d", &prods[prodCnt].codigo_produto,
                       &prods[prodCnt].qtd_estoque,
                       &prods[prodCnt].qtd_minima) == 3) {
        prodCnt++;
    }
    fclose(fpProd);

    /* ---------- Leitura de vendas (linha: situacao;codigo;quantidade;canal) ---------- */
    while (fscanf(fpVendas, "%d;%d;%d;%d", &vends[vendCnt].situacao_venda,
                       &vends[vendCnt].codigo_produto,
                       &vends[vendCnt].quantidade_vendida,
                       &vends[vendCnt].canal_venda) == 4) {
        vendCnt++;
    }
    fclose(fpVendas);

    /* ---------- Processamento dos dados ---------- */
    for (int i = 0; i < prodCnt; ++i) {
        prods[i].qtd_vendida = 0;

        for (int j = 0; j < vendCnt; ++j) {
            if (vends[j].codigo_produto == prods[i].codigo_produto) {
                prods[i].qtd_vendida += vends[j].quantidade_vendida;
            }
        }

        /* Necessidade de transferência = min - estoque (zero se negativo) */
        int necessidade = prods[i].qtd_minima - prods[i].qtd_estoque;
        if (necessidade < 0) necessidade = 0;
        prods[i].necessidade_transferencia = necessidade;

        /* Quantidade a transferir = vendida - necessidade (zero se negativo) */
        prods[i].qtd_transferencia = prods[i].qtd_vendida - necessidade;
        if (prods[i].qtd_transferencia < 0) prods[i].qtd_transferencia = 0;
    }

    /* ---------- Escrever TRANSFERE.txt ---------- */
    FILE *outTrans = fopen("TRANSFERE.txt", "w");
    if (!outTrans) {
        perror("Erro ao abrir 'TRANSFERE.txt'");
        return 1;
    }
    for (int i = 0; i < prodCnt; ++i) {
        fprintf(outTrans,
                 "%05d;%03d;%03d;%03d;%03d;%03d\n",
                 prods[i].codigo_produto,
                 prods[i].qtd_estoque,
                 prods[i].qtd_minima,
                 prods[i].qtd_vendida,
                 prods[i].necessidade_transferencia,
                 prods[i].qtd_transferencia);
    }
    fclose(outTrans);

    /* ---------- Escrever divergencias.txt ---------- */
    FILE *outDiv = fopen("divergencias.txt", "w");
    if (!outDiv) {
        perror("Erro ao abrir 'divergencias.txt'");
        return 1;
    }
    for (int i = 0; i < vendCnt; ++i) {
        for (int j = 0; j < prodCnt; ++j) {
            if (vends[i].codigo_produto == prods[j].codigo_produto) {
                if (vends[i].quantidade_vendida > prods[j].qtd_estoque) {
                    fprintf(outDiv,
                             "Produto %05d: venda de %03d unidades com estoque insuficiente (%03d unidades)\n",
                             vends[i].codigo_produto,
                             vends[i].quantidade_vendida,
                             prods[j].qtd_estoque);
                }
                if (vends[i].situacao_venda == 1 && vends[i].quantidade_vendida > 10) {
                    fprintf(outDiv,
                             "Produto %05d: venda de %03d unidades com situacao de venda invalida (%d)\n",
                             vends[i].codigo_produto,
                             vends[i].quantidade_vendida,
                             vends[i].situacao_venda);
                }
            }
        }
    }
    fclose(outDiv);

    return 0;
}
```

### Explicação rápida das alterações principais

1. **Leitura dos arquivos**  
   - Utilizamos `fscanf` diretamente com o formato que contém os separadores (`;`).  
   - Para produtos lemos apenas os três primeiros números (`codigo;estoque;min`), pois esses são os únicos que aparecem no arquivo; os outros campos serão preenchidos depois.

2. **Estruturas**  
   - Definimos as mesmas estruturas, mas agora usamos vetores estáticos (`prods[]`, `vends[]`) com tamanho suficiente para os casos de teste. Se o arquivo contiver mais linhas, basta aumentar o tamanho.

3. **Preenchimento dos campos ausentes**  
   - Após ler as vendas, já temos `situacao_venda`, `codigo_produto`, `quantidade_vendida` e `canal_venda`.  
   - Os campos `qtd_vendida`, `necessidade_transferencia` e `qtd_transferencia` são calculados posteriormente no laço de processamento.

4. **Cálculo de `necessidade_transferencia` e `qtd_transferencia`**  
   - `necessidade = qtd_minima - qtd_estoque`; se negativo → 0.  
   - `qtd_transferencia = qtd_vendida - necessidade`; se negativo → 0.

5. **Formatação de saída**  
   - `fprintf` usa o mesmo separador `;` entre os campos e o formato `%05d;%03d;%03d;%03d;%03d;%03d` (cinco grupos).  
   - O quarto grupo (`%03d`) corresponde a `qtd_vendida`.

6. **Loops de divergências**  
   - Agora `i` itera sobre `vends` (vendas) e `j` sobre `prods` (produtos), comparando `vends[i].codigo_produto` com `prods[j].codigo_produto`.  
   - As mensagens são escritas exatamente como solicitado.

7. **Tratamento de erros**  
   - Cada `fopen` é verificado; se falhar, imprimimos `perror` e retornamos com código de erro.

Com essas correções o programa deve:

- Ler corretamente os dois arquivos de texto.  
- Preencher todos os campos dos estruturas.  
- Calcular a quantidade a transferir e as divergências.  
- Gerar os arquivos `TRANSFERE.txt` e `divergencias.txt` contendo as informações esperadas.

